import {ToolRegistry} from './registry.js';
import {setLogger} from '../../shared/logger.js';
import type {Logger} from '../../shared/logger.js';

describe('ToolRegistry', () => {
  afterEach(() => {
    setLogger(undefined);
  });

  it('throws at registration time naming the tool for an uncompilable schema', () => {
    const registry = new ToolRegistry();

    expect(() =>
      registry.register(
        {
          name: 'broken_lookup',
          description: 'Tool with an invalid JSON Schema type',
          inputSchema: {
            type: 'object',
            properties: {
              query: {type: 'not-a-json-schema-type'},
            },
          },
        },
        async () => 'unreachable'
      )
    ).toThrow(/broken_lookup/);
  });

  it('registers a tool requiring a location string, calls execute with {}, and asserts the returned result names location as required and the executor call count is 0', async () => {
    const registry = new ToolRegistry();
    let calls = 0;
    registry.register(
      {
        name: 'test_tool',
        description: 'desc',
        inputSchema: {
          type: 'object',
          properties: {location: {type: 'string'}},
          required: ['location'],
        },
      },
      async () => {
        calls++;
        return 'ok';
      }
    );

    const response = await registry.execute('test_tool', {});
    expect(response.result).toMatch(/location/i);
    expect(response.result).toMatch(/required/i);
    expect(calls).toBe(0);
  });

  it('asserts valid input with an unlisted extra property is passed through to the executor unchanged', async () => {
    const registry = new ToolRegistry();
    let receivedInput: Record<string, unknown> | undefined;
    registry.register(
      {
        name: 'test_tool',
        description: 'desc',
        inputSchema: {
          type: 'object',
          properties: {known: {type: 'string'}},
        },
      },
      async input => {
        receivedInput = input;
        return 'ok';
      }
    );

    const input = {known: 'val', extra: 'unlisted'};
    await registry.execute('test_tool', input);
    expect(receivedInput).toEqual(input);
  });

  it('asserts a wrong-typed field is rejected with a message naming the field path and expected type, without containing the offending value', async () => {
    const registry = new ToolRegistry();
    registry.register(
      {
        name: 'test_tool',
        description: 'desc',
        inputSchema: {
          type: 'object',
          properties: {age: {type: 'number'}},
        },
      },
      async () => 'ok'
    );

    const response = await registry.execute('test_tool', {age: 'not-a-number'});
    expect(response.result).toMatch(/age/);
    expect(response.result).toMatch(/number/);
    expect(response.result).not.toContain('not-a-number');
  });

  it('asserts a static tool schema is compiled once across ten execute calls', async () => {
    const registry = new ToolRegistry();
    let accessCount = 0;
    const inputSchema = {
      type: 'object' as const,
      get properties() {
        accessCount++;
        return {location: {type: 'string'}};
      },
    };

    registry.register(
      {
        name: 'test_tool',
        description: 'desc',
        inputSchema: inputSchema as any,
      },
      async () => 'ok'
    );

    const initialCount = accessCount;
    for (let i = 0; i < 10; i++) {
      await registry.execute('test_tool', {location: 'here'});
    }
    expect(accessCount).toBe(initialCount);
  });

  it('asserts a function-valued tool definition whose returned schema differs between calls is validated against the schema current at that call', async () => {
    const registry = new ToolRegistry();
    let schemaType = 'string';
    registry.register(
      () => ({
        name: 'dynamic_tool',
        description: 'desc',
        inputSchema: {
          type: 'object',
          properties: {val: {type: schemaType}},
        },
      }),
      async () => 'ok'
    );

    const res1 = await registry.execute('dynamic_tool', {val: 123});
    expect(res1.result).toMatch(/string/);

    schemaType = 'number';
    const res2 = await registry.execute('dynamic_tool', {val: 'abc'});
    expect(res2.result).toMatch(/number/);

    const res3 = await registry.execute('dynamic_tool', {val: 123});
    expect(res3.result).toBe('ok');
  });

  it('throws Unknown tool: <name> for an unregistered name', async () => {
    const registry = new ToolRegistry();
    await expect(registry.execute('missing', {})).rejects.toThrow('Unknown tool: missing');
  });

  it('asserts a rejected payload containing an identifying field produces no log line and no returned text containing that field value', async () => {
    const recordedLogs: string[] = [];
    const recordLine = (_cat: string, _msg: string, fields?: Record<string, unknown>) => {
      recordedLogs.push(JSON.stringify(fields));
    };
    const logger: Logger = {
      info: recordLine,
      warn: recordLine,
      error: recordLine,
      debug: recordLine,
    };
    setLogger(logger);

    const registry = new ToolRegistry();
    registry.register(
      {
        name: 'secret_tool',
        description: 'desc',
        inputSchema: {
          type: 'object',
          properties: {ssn: {type: 'string'}},
        },
      },
      async () => 'ok'
    );

    const secretValue = 'SECRET-12345';
    const response = await registry.execute('secret_tool', {ssn: secretValue as any}); // Force a type mismatch

    expect(response.result).not.toContain(secretValue);
    expect(recordedLogs.some(log => log.includes(secretValue))).toBe(false);
  });
});

